create or replace function public.schedule_integration_event_retry(p_event_id uuid,p_error text default null) returns boolean language plpgsql security definer set search_path=public as $$ declare v_attempt int; v_delay int; begin select claim_attempt into v_attempt from public.integration_events where id=p_event_id for update; if not found then return false; end if; v_attempt:=coalesce(v_attempt,0); if v_attempt>=8 then update public.integration_events set status='failed',error_message=coalesce(p_error,error_message),processed_at=now() where id=p_event_id; return false; end if; v_delay:=least(3600,greatest(60,pow(2,greatest(v_attempt-1,0))::int*60)); update public.integration_events set status='retry',error_message=p_error,next_retry_at=now()+make_interval(secs=>v_delay) where id=p_event_id; return true; end; $$; revoke execute on function public.schedule_integration_event_retry(uuid,text) from public,anon,authenticated; grant execute on function public.schedule_integration_event_retry(uuid,text) to service_role; create index if not exists integration_events_claimed_idx on public.integration_events (claimed_at desc) where status='processing';